---@class CommonCountdownText
local CommonCountdownText = Class("CommonCountdownText")
function CommonCountdownText:__init()
    self.TxtTime = nil
    self.timer = nil
    self.countDown = nil

end

function CommonCountdownText:__delete()
    self.TxtTime = nil
    self.timer = nil
    self.countDown = nil

    self.controller = nil
end

function CommonCountdownText:GetCountDown()
    return self.countDown
end


function CommonCountdownText:Awake()
    self.TxtTime = self.controller.gameObject.transform:GetComponent(typeof(Text))
    if isNull(self.TxtTime) then
        self.TxtTime = self.controller.gameObject.transform:GetComponent(typeof(TextMeshProUGUI))
    end
    if isNull(self.TxtTime) then
        printError("The Component -Text- or -TextMeshProUGUI- is Missing !!!")
    end
end

---开始倒计时
---@param leftTime number
---@param formatType number 
---@param timeOverCb fun():void
function CommonCountdownText:StartLeftSecond(leftTime, formatType, timeOverCb)
    if leftTime > 0 then
        self:StopTimer()
        leftTime = checkNumber(leftTime)
        self.timer = CDTimerModule:AddCD(1, function (count, id)
            self.TxtTime.text = self:FormatLeftSecond(count, formatType)
            self.countDown = count
            if count == 0 then
                if type(timeOverCb) == 'function' then
                    timeOverCb()
                end
            end
        end, leftTime, true, true, true)
    end
end



function CommonCountdownText:FormatLeftSecond(second, formatType)
    if formatType == 1 then
        local minute = math.floor(second / 60)
        local hour = math.floor(minute / 60)
        local lastMinute = minute - hour * 60
        local str
        if hour > 0 then
            str = string.format("%02d小时%02d分", hour, lastMinute)
        elseif lastMinute <= 1 then
            str = "1分"
        else
            str = string.format("%02d分", lastMinute)
        end
        return str
    elseif formatType == 2 then
        return CfUtils.GetTimeHMS2(second)
    elseif formatType == 3 then
        local days, remainder = math.modf(second / 86400)
        local hours = math.floor(remainder * 24) --余数乘上一天24小时
        if hours == 0  then
            hours = 1
        end
        return table.concat({days, localize("天"), hours, localize("小时")})
    elseif formatType == 4 then
        return second
    elseif formatType == 5 then
        return CfUtils.GetTimeHMS5(second)
    end
end

function CommonCountdownText:StopTimer()
    if not isNull(self.timer) then
        self.countDown = nil
        CDTimerModule:RemoveCD(self.timer)
        self.timer = nil
    end
end

function CommonCountdownText:OnDestroy()
    self:StopTimer()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return CommonCountdownText